//! `graphite`: Studio graphite: true neutral greys, no tint, with one electric-violet accent.
//!
//! Generated by `examples/palette_gen.rs` from a few design tokens; the tables below are plain
//! literals. Accent fill: light `#6a52ff`, dark `#8a7dff`.

use crate::colour::Colour;
use crate::palette::{Palette, Role};

/// The palette's id.
pub const ID: &str = "graphite";

/// Graphite.
pub const PALETTE: Palette = Palette {
    id: ID,
    name: "Graphite",
    selectable: false,
    light,
    dark,
};

